%[text] # BC121 Configuration A: effect of the radius of the sphere around the model
%[text] **J.G. Vermond, JVsound**
%[text] Prepared on 2026-10-15. The air around the cabinet in the Ansys Mechanical model is enclosed by a sphere. This script shows how the radius of that sphere changes the results of configuration A (one cabinet lying, flat diaphragm), at the same mesh. The largest radius is the reference: when a smaller sphere gives the same results, it is large enough. The averaged pressure on the front and the rear of the diaphragm, the SPL at 1 m (a microphone in the mesh) and the SPL at the microphones outside the mesh at 5 and 10 m are compared.
%[text:tableOfContents]{"heading":"Contents"}
%[text] - pressure on the diaphragm (`diaf` and `diar`) due to the imposed velocity of 1 mm/s
%[text] - the SPL of the loudspeaker system, calculated with the FEA enclosure at 28.3 V RMS
%[text] - SPL at 1 m, 5 m and 10 m
%[text] - summary of the differences between the radii \
%%
%[text] ## Settings
%[text] The radii are listed from small to large. The exports of Mechanical (in MPa) are in `Simulation\SphereRadiusStudy\<radius> mm\`, with the same files as the mesh study. The names of the diaphragm and the 1 m files differ between the folders (`Average Pressure Diaphragm Front.txt` or `Average Frequency Response Front.txt`, `Pressure Mic1m.txt` or `Frequency Response Mic1m.txt`); the script takes the one that exists.
radii = [2000 2250 2500]; % Radius of the sphere in [mm], small to large
micDistances = [5 10]; % Far-field microphones outside the mesh in [m]
tolerance = 1; % Allowed SPL difference with the largest radius in [dB]
sourceVoltage = 28.3; % RMS voltage of the amplifier in [V]
diaphragmVelocity = 1e-3; % Velocity imposed on the diaphragm in the FEA model in [m/s]
exportFolder = fullfile(currentProject().RootFolder,"Simulation","SphereRadiusStudy");
pRef = 20e-6; % Reference pressure for the SPL in [Pa]
radiusLabels = radii + " mm";
micNames = micDistances + " m";
numRadius = numel(radii);
numMic = numel(micDistances);
%%
%[text] ## Read the FEA results
%[text] The complex pressure is the real and the imaginary part of the export, converted from MPa to Pa. The far-field microphones are read with `readFarField`. All radii must have the same frequencies, otherwise the differences cannot be taken.
readExport = @(file) readmatrix(file,FileType="text",NumHeaderLines=1);
pickFile = @(folder,names) fullfile(folder,names(find(arrayfun(@(n) isfile(fullfile(folder,n)),names),1)));
pFront = []; pRear = []; pMeshMic = []; pFarMic = cell(1,numMic);
for m = 1:numRadius
    folder = fullfile(exportFolder,radii(m) + " mm");
    front = readExport(pickFile(folder,["Average Pressure Diaphragm Front.txt" "Average Frequency Response Front.txt"]));
    rear = readExport(pickFile(folder,["Average Pressure Diaphragm Rear.txt" "Average Frequency Response Rear.txt"]));
    mesh1m = readExport(pickFile(folder,["Pressure Mic1m.txt" "Frequency Response Mic1m.txt"]));
    if m == 1
        frequency = front(:,1);
    end
    sameFrequency = @(x) size(x,1) == numel(frequency) && max(abs(x(:,1) - frequency)) < 1e-3*max(frequency);
    assert(sameFrequency(front) && sameFrequency(rear) && sameFrequency(mesh1m), ...
        "Radius %g mm has other frequencies than radius %g mm.",radii(m),radii(1))
    pFront(:,m) = (front(:,4) + 1i*front(:,5))*1e6; %#ok<SAGROW>
    pRear(:,m) = (rear(:,4) + 1i*rear(:,5))*1e6; %#ok<SAGROW>
    pMeshMic(:,m) = (mesh1m(:,4) + 1i*mesh1m(:,5))*1e6; %#ok<SAGROW>
    farField = readFarField(folder,"Mic" + micDistances + "m");
    for k = 1:numMic
        assert(sameFrequency([farField(k).Frequency.' farField(k).Frequency.']), ...
            "Microphone %s of radius %g mm has other frequencies.",micNames(k),radii(m))
        pFarMic{k}(:,m) = farField(k).Pressure.';
    end
end
disp("Radii read: " + join(radiusLabels,", ")) %[output:172bc490]
%[text] The difference of a radius is taken against the largest radius, so it is zero for the last column. `spl` is only used to express the diaphragm pressure as a level in the summary, from the RMS value, so the amplitude divided by $ \\sqrt{2} $.
spl = @(p) 20*log10(abs(p)/sqrt(2)/pRef);
diffLargest = @(x) x - x(:,end);
splUnit = "dB re 20 " + char(181) + "Pa";
%%
%[text] ## Pressure on the diaphragm
%[text] Magnitude of the pressure averaged over `diaf` and `diar` (amplitude in Pa) for the imposed velocity of 1 mm/s, and the difference of the smaller radii with the largest radius.
tiledlayout(2,2) %[output:29bb6392]
nexttile %[output:29bb6392]
loglog(frequency,abs(pFront)), grid on %[output:29bb6392]
ylabel("Pressure (Pa)"), legend(radiusLabels,Location="best"), title("diaf (front)") %[output:29bb6392]
nexttile %[output:29bb6392]
loglog(frequency,abs(pRear)), grid on %[output:29bb6392]
title("diar (rear)") %[output:29bb6392]
nexttile %[output:29bb6392]
semilogx(frequency,diffLargest(abs(pFront))), grid on %[output:29bb6392]
xlabel("Frequency (Hz)"), ylabel("Difference (Pa)"), title("diaf (front)") %[output:29bb6392]
nexttile %[output:29bb6392]
semilogx(frequency,diffLargest(abs(pRear))), grid on %[output:29bb6392]
xlabel("Frequency (Hz)"), ylabel("Difference (Pa)"), title("diar (rear)") %[output:29bb6392]
%[text] Check on the exports: the front and the rear of the diaphragm must differ.
frontEqualsRear = max(abs(pFront - pRear),[],"all") < 1e-6*max(abs(pFront),[],"all") %[output:3a5e6901]
%%
%[text] ## Calculate the SPL with the loudspeaker system
%[text] The SPL at a microphone is calculated per radius with an `lspsys` that has a `comp.FeaEnclosure` and the B&C 21SW152-8 as driver, driven with `sourceVoltage` (RMS). The enclosure gets the averaged pressure on the front and the rear of the diaphragm of that radius. The pressure at the microphone is the transfer of the FEA model times the volume velocity of the system.
splMesh1m = zeros(numel(frequency),numRadius);
splFarMic = repmat({zeros(numel(frequency),numRadius)},1,numMic);
asData = @(p) struct(Frequency=frequency.',Pressure=p.');
for m = 1:numRadius
    sys = lspsys;
    sys.SourceVoltage = sourceVoltage;
    sys.Enclosure = comp.FeaEnclosure;
    sys.Enclosure.PressureFront = asData(pFront(:,m));
    sys.Enclosure.PressureRear = asData(pRear(:,m));
    sys.Enclosure.DiaphragmVelocity = diaphragmVelocity;
    sys.Enclosure.Driver = comp.Driver;
    sys.Enclosure.Driver.Re = 6;
    sys.Enclosure.Driver.Le = 2.2e-3;
    sys.Enclosure.Driver.Qes = 0.38;
    sys.Enclosure.Driver.Qms = 6.4;
    sys.Enclosure.Driver.Fs = 32;
    sys.Enclosure.Driver.Sd = 1680e-4;
    sys.Enclosure.Driver.Vas = 200e-3;
    sys.Enclosure.Driver.Znom = 8;
    sys.Enclosure.Driver.Zmin = 7;
    sys.Enclosure.Driver.Pnom = 2000;
    sys.Enclosure.Driver.Xvar = 16e-3;
    sys.Frequency = sys.Enclosure.Frequency;
    sys.Enclosure.PressureFarField = asData(pMeshMic(:,m));
    res = sys.createResult;
    splMesh1m(:,m) = res.SoundPressureLevel(:);
    for k = 1:numMic
        sys.Enclosure.PressureFarField = asData(pFarMic{k}(:,m));
        res = sys.createResult;
        splFarMic{k}(:,m) = res.SoundPressureLevel(:);
    end
end
%%
%[text] ## SPL at 1 m (in the mesh domain)
%[text] The SPL at the microphone in the mesh, on the floor 1 m from the mouth of the horn, at the source voltage.
tiledlayout(2,1) %[output:547d58e1]
nexttile %[output:547d58e1]
semilogx(frequency,splMesh1m), grid on %[output:547d58e1]
ylabel(splUnit), legend(radiusLabels,Location="best"), title("Microphone at 1 m") %[output:547d58e1]
nexttile %[output:547d58e1]
semilogx(frequency,diffLargest(splMesh1m)), grid on %[output:547d58e1]
yline([-tolerance tolerance],"--k",HandleVisibility="off") %[output:547d58e1]
xlabel("Frequency (Hz)"), ylabel("Difference (dB)"), title("Difference with the largest radius") %[output:547d58e1]
%%
%[text] ## SPL at 5 and 10 m (outside the mesh domain)
%[text] The far-field microphones are calculated from the surface of the sphere, so they are the most sensitive to its radius. Top: the SPL, bottom: the difference with the largest radius, with the tolerance as dashed lines.
tiledlayout(2,numMic) %[output:29e9cbc8]
for k = 1:numMic %[output:group:46d68f2b]
    nexttile(k) %[output:29e9cbc8]
    semilogx(frequency,splFarMic{k}), grid on
    title("Microphone at " + micNames(k)), ylabel(splUnit)
    if k == 1
        legend(radiusLabels,Location="best")
    end
    nexttile(numMic + k)
    semilogx(frequency,diffLargest(splFarMic{k})), grid on
    yline([-tolerance tolerance],"--k",HandleVisibility="off")
    xlabel("Frequency (Hz)"), ylabel("Difference (dB)")
end %[output:group:46d68f2b]
%%
%[text] ## Summary
%[text] Maximum and RMS difference over all frequencies of the smaller radii with the largest radius, and whether the next to largest radius is within `tolerance`. The microphones are compared as the SPL of the loudspeaker system at `sourceVoltage`; the diaphragm pressure is compared as a level, so its difference is the ratio of the pressures in dB.
quantity = ["Front diaphragm" "Rear diaphragm" "Mic 1 m" "Mic " + micNames].';
levels = {spl(pFront) spl(pRear) splMesh1m};
for k = 1:numMic
    levels{end+1} = splFarMic{k}; %#ok<SAGROW>
end
summary = table(quantity,VariableNames="Quantity");
for m = 1:numRadius-1
    summary.("Max " + radii(m) + " mm") = cellfun(@(x) max(abs(x(:,m) - x(:,end))),levels).';
    summary.("RMS " + radii(m) + " mm") = cellfun(@(x) sqrt(mean((x(:,m) - x(:,end)).^2)),levels).';
end
summary.("Within tolerance") = summary.("Max " + radii(end-1) + " mm") < tolerance;
disp(summary) %[output:138f8612]
%[text] A quantity within tolerance is not changed by a larger sphere. For the others, the sphere is too small or the radius changes the result.

